package com.yuegang.zhihui.product.application;import com.yuegang.zhihui.product.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class ProductConfiguration{@Bean ProductService productService(DataSource d){return new ProductService(d);}@Bean ProductAdminVerifier productAdminVerifier(@Value("${YGH_INTERNAL_REQUEST_HMAC_BASE64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new ProductAdminVerifier(k);}finally{Arrays.fill(k,(byte)0);}}}
